{"cards": [{"node_code": "N_a9d5e5cf7a3e61a1", "definition": "指用于设置航标的实体硬件设施，包括灯塔、灯桩、浮标、立标等结构体，以及其配套的灯光、雷达反射器、太阳能供电等附属装置。", "boundary": "本节点聚焦于航标的物理实体及其工程技术。边界在于区分“设备”与“理论/规范”（前者侧重硬件结构与制造，后者侧重原理与标准）；区分“设备”与“配置”（前者侧重单体设施，后者侧重空间布局与选位）。若内容涉及航标的具体结构设计、材料选择、制造工艺或电气系统，归入本节点。", "includes": ["灯塔、灯桩、浮标等航标结构体的设计与建造", "航标灯光、音响、雷达反射器等信号装置的技术", "航标供电系统（如太阳能、风能）及维护设施"], "excludes": ["航标布设的数学模型、光学原理等纯理论研究", "航标选位的水文勘测与规划方案", "航标日常巡检、维修的管理流程"], "sibling_distinctions": [{"other_code": "N_b6d2b596d7b60253", "rule": "本节点侧重硬件实体与工程技术；航标技术理论侧重光学、水力学等基础科学原理。"}, {"other_code": "N_6fcc6dae8af1ba5e", "rule": "本节点侧重具体设备的技术实现；航标技术规范与标准侧重行业准则、法规及参数规定。"}, {"other_code": "N_8c8696066809d74f", "rule": "本节点侧重单体设备的构造；航标配置与勘探选位侧重航标在航道中的空间分布与位置确定。"}], "cross_boundary_rule": "若内容涉及航标设备的选型依据，侧重设备性能参数归入本节点，侧重选位逻辑归入配置节点。"}, {"node_code": "N_0ebab813a1aac7e8", "definition": "指用于辅助船舶通过急流、险滩等复杂航段的专用设施，包括绞滩站、绞盘、缆绳系统及相关辅助机械，旨在提供额外动力或控制船舶航向。", "boundary": "本节点聚焦于“绞滩”这一特定助航方式及其设备。边界在于区分“绞滩”与“普通航标”（前者提供动力或强力约束，后者主要起指示作用）；区分“绞滩”与“船闸”（前者在开放或半开放水域作业，后者为封闭水位调节设施）。若内容涉及绞滩站的选址、绞盘机械结构、缆绳张力控制或绞滩作业技术，归入本节点。", "includes": ["绞滩站的结构设计与建设", "绞盘、卷扬机等核心机械设备的原理与应用", "绞滩作业的操作技术、缆绳管理及安全规程"], "excludes": ["一般性航标（如灯塔、浮标）的技术与管理", "船闸、升船机等封闭或半封闭通航建筑物", "航道疏浚或整治工程"], "sibling_distinctions": [{"other_code": "N_a9d5e5cf7a3e61a1", "rule": "本节点侧重提供动力或强力辅助的绞滩设备；航标设备侧重指示航道位置的标志设施。"}, {"other_code": "N_c06e2af75a3b31b1", "rule": "本节点侧重绞滩设备的技术原理与作业方法；助航设备使用管理侧重全类型助航设备的行政管理与维护制度。"}], "cross_boundary_rule": "若内容涉及绞滩站与航标的联合调度，侧重绞滩机械操作归入本节点，侧重整体调度策略归入管理节点。"}, {"node_code": "N_c06e2af75a3b31b1", "definition": "指对各类助航设备（包括航标、绞滩设备等）进行日常运行、维护、检修、更新及行政管理的制度、流程与技术方法。", "boundary": "本节点聚焦于助航设备的“管理”与“使用”环节。边界在于区分“管理”与“设备技术”（前者侧重运维流程、法规执行、状态监测，后者侧重设备本身的结构与原理）；区分“管理”与“配置”（前者侧重既有设备的维护，后者侧重新设备的规划与选位）。若内容涉及助航设备的巡检制度、故障处理、寿命评估、信息化管理平台或法律法规执行，归入本节点。", "includes": ["助航设备的日常巡检、维护保养与故障排除", "助航设备运行状态的监测、评估与更新改造", "助航设备管理的法律法规、行政制度及信息化系统"], "excludes": ["航标或绞滩设备的具体结构设计、制造工艺", "航标选位的水文勘测与规划方案", "船舶上的导航设备管理"], "sibling_distinctions": [{"other_code": "N_a9d5e5cf7a3e61a1", "rule": "本节点侧重设备的运维与管理流程；航标设备侧重设备的硬件技术与构造。"}, {"other_code": "N_0ebab813a1aac7e8", "rule": "本节点侧重通用或特定的管理流程；绞滩及设备侧重绞滩特有的机械技术与作业方法。"}, {"other_code": "N_8c8696066809d74f", "rule": "本节点侧重既有设备的管理；航标配置与勘探选位侧重新设航标的规划与定位。"}], "cross_boundary_rule": "若内容涉及助航设备的技术改造，侧重管理决策与流程归入本节点，侧重具体技术改造方案归入相应设备节点。"}]}
